import numpy as np
from collections import deque
d = np.load('source_pixels.npz')['rgb'].astype(int)
bg = np.median(d,axis=0)

def comps(mask,minsz=10):
    H,W=mask.shape
    lab=-np.ones((H,W),np.int32); out=[]
    for sy in range(H):
        for sx in range(W):
            if mask[sy,sx] and lab[sy,sx]<0:
                q=deque([(sy,sx)]);lab[sy,sx]=0;pts=[]
                while q:
                    y,x=q.popleft();pts.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and mask[ny,nx] and lab[ny,nx]<0:
                            lab[ny,nx]=0;q.append((ny,nx))
                if len(pts)>=minsz:
                    p=np.array(pts); out.append((p[:,1].mean(),p[:,0].mean(),len(pts)))
    return out

for fi in range(0,96,6):
    diff=np.abs(d[fi]-bg).sum(2)
    m=diff>70
    cs=comps(m,8)
    print(fi, sorted([(round(x,1),round(y,1),n) for x,y,n in cs], key=lambda t:-t[2])[:8])
