import numpy as np
d = np.load('source_pixels.npz')['rgb'].astype(np.float32)

def make_template(cy,cx,r=3):
    yy,xx=np.mgrid[-r:r+1,-r:r+1]
    disc=(xx**2+yy**2)<=r*r
    return d[0,cy-r:cy+r+1,cx-r:cx+r+1].copy(),disc

def track(tpl,disc,start):
    H,W=d.shape[1:3]; r=(tpl.shape[0]-1)//2
    pos=np.array(start,float); traj=[]
    for fi in range(96):
        fr=d[fi]; best=None
        y0=max(r,int(round(pos[0]))-12); y1=min(H-r-1,int(round(pos[0]))+12)
        x0=max(r,int(round(pos[1]))-12); x1=min(W-r-1,int(round(pos[1]))+12)
        for y in range(y0,y1+1):
            for x in range(x0,x1+1):
                sad=np.abs(fr[y-r:y+r+1,x-r:x+r+1]-tpl)[disc].sum()
                if best is None or sad<best[0]: best=(sad,y,x)
        _,by,bx=best
        # subpixel via local SAD surface quadratic interpolation
        s=np.zeros((3,3))
        for j,dy in enumerate((-1,0,1)):
            for i,dx in enumerate((-1,0,1)):
                s[j,i]=np.abs(fr[by+dy-r:by+dy+r+1,bx+dx-r:bx+dx+r+1]-tpl)[disc].sum()
        dx=0.5*(s[1,0]-s[1,2])/(s[1,0]+s[1,2]-2*s[1,1]+1e-6)
        dy=0.5*(s[0,1]-s[2,1])/(s[0,1]+s[2,1]-2*s[1,1]+1e-6)
        dx=np.clip(dx,-1,1); dy=np.clip(dy,-1,1)
        traj.append((bx+dx,by+dy)); pos=np.array([by+dy,bx+dx])
    return np.array(traj)

tplW,discW=make_template(95,85); tplK,discK=make_template(71,126)
tw=track(tplW,discW,(95,85)); tk=track(tplK,discK,(71,126))
np.set_printoptions(precision=2,suppress=True)
print('WHITE x,y per frame:')
for i in range(96):
    if i%3==0: print(i, tw[i])
print('DARK:')
for i in range(96):
    if i%3==0: print(i, tk[i])
np.save('.tmp/tw_sub.npy',tw); np.save('.tmp/tk_sub.npy',tk)
EOF"
